\draw[da] (Q)--(R);
\draw[sa] (S)--(R);
\draw[da] (P)--(S);
\draw (P)--(R);
\draw (0.3,0)--(0.3,0.3)--(0,0.3);
\draw (4.2,0)--(4.2,0.3)--(4.5,0.3);
